      prepareAppImageTools: async ({ directory }) => {
        overlay = directory
        mkdirSync(directory)
        return { APPIMAGE_TOOLS_PATH: directory, ORCA_PR_APPIMAGE_MKSQUASHFS: 'original tool' }
      },
      runBuilder: async (args, environment) => {
